   260→pub fn validate_ring_buffer_capacity(capacity: u32) -> bool {
   261→    capacity >= 256 && capacity <= 65536 && (capacity & (capacity - 1)) == 0  // power of 2
   262→}
   263→
   264→pub fn validate_throughput(throughput: u64) -> bool {
   265→    // 목표: > 1M events/sec = 1000000
   266→    throughput > 1000000
   267→}
   268→
   269→pub fn validate_loss_rate(loss_rate: f32) -> bool {
