   271→    loss_rate == 0.0
   272→}
   273→
   274→pub fn validate_batch_size(batch_size: u32) -> bool {
   275→    batch_size >= 1 && batch_size <= 1024
   276→}
   277→
   278→pub fn validate_pipeline_latency(latency_ns: u64) -> bool {
   279→    // 목표: < 1µs per batch = 1000ns
   280→    latency_ns < 1000
   281→}
