     7→// ========== Threat Types (8가지) ==========
     8→
     9→#[derive(Clone, Copy, Debug)]
    10→pub enum ThreatType {
    11→    Normal,                    // C0
    12→    ZeroDay,                   // C1
    13→    PrivilegeEscalation,      // C2
    14→    CodeInjection,            // C3
    15→    DataExfiltration,         // C4
    16→    PersistenceMechanism,     // C5
    17→    LateralMovement,          // C6
    18→    CoverageEvasion,          // C7
    19→}
    20→
    21→// ========== Neural Network Weights ==========
    22→
    23→pub struct SimpleNN {
    24→    // L1: 16→32
    25→    pub w1: Vec<f64>,
    26→    pub b1: Vec<f64>,
    27→    // L2: 32→16
    28→    pub w2: Vec<f64>,
    29→    pub b2: Vec<f64>,
    30→    // L3: 16→8
    31→    pub w3: Vec<f64>,
    32→    pub b3: Vec<f64>,
    33→}
    34→
    35→impl SimpleNN {
    36→    pub fn new() -> Self {
    37→        Self {
    38→            w1: vec![0.01; 512],   // 16×32
    39→            b1: vec![0.0; 32],
    40→            w2: vec![0.01; 512],   // 32×16
    41→            b2: vec![0.0; 16],
    42→            w3: vec![0.01; 128],   // 16×8
    43→            b3: vec![0.0; 8],
    44→        }
    45→    }
    46→
    47→    pub fn relu(x: f64) -> f64 {
    48→        if x > 0.0 { x } else { 0.0 }
    49→    }
    50→
    51→    pub fn softmax(logits: &[f64]) -> Vec<f64> {
    52→        let max = logits.iter().fold(f64::NEG_INFINITY, |a, &b| a.max(b));
    53→        let exp_vals: Vec<f64> = logits.iter().map(|x| (x - max).exp()).collect();
    54→        let sum: f64 = exp_vals.iter().sum();
    55→        exp_vals.iter().map(|x| x / sum).collect()
    56→    }
    57→
    58→    pub fn forward(&self, input: &[f64]) -> Vec<f64> {
    59→        // L1: input(16) @ w1(16×32) + b1(32)
    60→        let mut z1 = vec![0.0; 32];
    61→        for i in 0..32 {
    62→            z1[i] = self.b1[i];
    63→            for j in 0..16 {
    64→                z1[i] += input[j] * self.w1[j * 32 + i];
    65→            }
    66→        }
    67→        let a1: Vec<f64> = z1.iter().map(|&x| Self::relu(x)).collect();
    68→
    69→        // L2: a1(32) @ w2(32×16) + b2(16)
    70→        let mut z2 = vec![0.0; 16];
    71→        for i in 0..16 {
    72→            z2[i] = self.b2[i];
    73→            for j in 0..32 {
    74→                z2[i] += a1[j] * self.w2[j * 16 + i];
    75→            }
    76→        }
    77→        let a2: Vec<f64> = z2.iter().map(|&x| Self::relu(x)).collect();
    78→
    79→        // L3: a2(16) @ w3(16×8) + b3(8)
    80→        let mut z3 = vec![0.0; 8];
    81→        for i in 0..8 {
    82→            z3[i] = self.b3[i];
    83→            for j in 0..16 {
    84→                z3[i] += a2[j] * self.w3[j * 8 + i];
    85→            }
    86→        }
    87→
    88→        Self::softmax(&z3)
    89→    }
    90→}
    91→
    92→// ========== Rule-Based Classifier ==========
    93→
    94→pub struct RuleBasedClassifier;
    95→
    96→impl RuleBasedClassifier {
    97→    pub fn classify(features: &SyscallFeatureVector) -> (ThreatType, f64) {
    98→        // ModuleLoad 계열 → CodeInjection
    99→        if features.high_risk_syscall_count > 0.7 && features.memory_manip_rate > 0.6 {
   100→            return (ThreatType::CodeInjection, 0.85);
   101→        }
   102→
   103→        // SetUID/Chroot 계열 → PrivilegeEscalation
   104→        if features.privilege_rate > 0.6 && features.process_ctrl_rate > 0.5 {
   105→            return (ThreatType::PrivilegeEscalation, 0.80);
   106→        }
   107→
   108→        // Network 송수신 → DataExfiltration
   109→        if features.network_rate > 0.6 && features.repetition_factor < 0.3 {
   110→            return (ThreatType::DataExfiltration, 0.75);
   111→        }
   112→
   113→        // 반복 패턴 → PersistenceMechanism
   114→        if features.repetition_factor > 0.8 && features.sequence_entropy < 0.3 {
   115→            return (ThreatType::PersistenceMechanism, 0.70);
   116→        }
   117→
   118→        // 높은 엔트로피 + 프로세스 제어 → LateralMovement
   119→        if features.sequence_entropy > 0.7 && features.process_ctrl_rate > 0.5 {
   120→            return (ThreatType::LateralMovement, 0.65);
   121→        }
   122→
   123→        // 에러율 높음 + 권한 → CoverageEvasion
   124→        if features.return_error_rate > 0.6 && features.privilege_level > 0.5 {
   125→            return (ThreatType::CoverageEvasion, 0.60);
   126→        }
   127→
   128→        // 기본
   129→        (ThreatType::Normal, 0.1)
   130→    }
   131→}
   132→
   133→// ========== Anomaly Detector ==========
   134→
   135→pub struct AnomalyDetector;
   136→
   137→impl AnomalyDetector {
   138→    pub fn detect(features: &SyscallFeatureVector) -> f64 {
   139→        // 16개 특성의 이상치 점수 (0-1)
   140→        let scores = vec![
   141→            (features.file_io_rate * 0.8).min(1.0),
   142→            (features.process_ctrl_rate * 0.9).min(1.0),
   143→            (features.memory_manip_rate * 0.95).min(1.0),
   144→            (features.network_rate * 0.85).min(1.0),
   145→            (features.privilege_rate * 1.0).min(1.0),
   146→            features.bigram_anomaly,
   147→            features.trigram_anomaly,
   148→            features.fourgram_anomaly,
   149→            features.sequence_entropy,
   150→            features.repetition_factor,
   151→            features.burst_intensity,
   152→            (features.avg_duration_normalized * 0.5).min(1.0),
   153→            (features.timing_variance * 0.7).min(1.0),
   154→            features.privilege_level,
   155→            features.high_risk_syscall_count,
   156→            features.return_error_rate,
   157→        ];
   158→
   159→        let sum: f64 = scores.iter().sum();
   160→        (sum / scores.len() as f64).min(1.0)
   161→    }
   162→}
