   164→// ========== Ensemble Classifier ==========
   165→
   166→pub struct ThreatClassifier {
   167→    pub nn: SimpleNN,
   168→}
   169→
   170→impl ThreatClassifier {
   171→    pub fn new() -> Self {
   172→        Self {
   173→            nn: SimpleNN::new(),
   174→        }
   175→    }
   176→
   177→    pub fn classify(&self, features: &SyscallFeatureVector) -> (ThreatType, f64) {
   178→        let vec = features.to_vector();
   179→
   180→        // NN 추론: 60% 가중치
   181→        let nn_output = self.nn.forward(&vec);
   182→        let nn_class = nn_output
   183→            .iter()
   184→            .enumerate()
   185→            .max_by(|a, b| a.1.partial_cmp(b.1).unwrap())
   186→            .unwrap()
   187→            .0;
   188→        let nn_confidence = nn_output[nn_class];
   189→
   190→        // 규칙 기반: 30% 가중치
   191→        let (rule_type, rule_confidence) = RuleBasedClassifier::classify(features);
   192→
   193→        // 이상치 점수: 10% 가중치
   194→        let anomaly_score = AnomalyDetector::detect(features);
   195→
   196→        // 앙상블 결합
   197→        let final_confidence = 0.6 * nn_confidence + 0.3 * rule_confidence + 0.1 * anomaly_score;
   198→
   199→        // NN 클래스 선택 (높은 신뢰도)
   200→        let threat_type = match nn_class {
   201→            0 => ThreatType::Normal,
   202→            1 => ThreatType::ZeroDay,
   203→            2 => ThreatType::PrivilegeEscalation,
   204→            3 => ThreatType::CodeInjection,
   205→            4 => ThreatType::DataExfiltration,
   206→            5 => ThreatType::PersistenceMechanism,
   207→            6 => ThreatType::LateralMovement,
   208→            _ => ThreatType::CoverageEvasion,
   209→        };
   210→
   211→        (threat_type, final_confidence)
   212→    }
   213→
   214→    pub fn get_threat_probabilities(&self, features: &SyscallFeatureVector) -> Vec<f64> {
   215→        let vec = features.to_vector();
   216→        self.nn.forward(&vec)
   217→    }
   218→}
