    84→// ========== N-gram Extractor ==========
    85→
    86→pub struct NgramExtractor {
    87→    pub per_pid_windows: HashMap<u32, Vec<u8>>,
    88→    pub ngram_counts: HashMap<Vec<u8>, u32>,
    89→    pub normal_baseline: HashMap<Vec<u8>, f64>,
    90→}
    91→
    92→impl NgramExtractor {
    93→    pub fn new() -> Self {
    94→        Self {
    95→            per_pid_windows: HashMap::new(),
    96→            ngram_counts: HashMap::new(),
    97→            normal_baseline: HashMap::new(),
    98→        }
    99→    }
   100→
   101→    pub fn add_syscall(&mut self, pid: u32, syscall_id: u8) {
   102→        let window = self.per_pid_windows.entry(pid).or_insert_with(Vec::new);
   103→        window.push(syscall_id);
   104→
   105→        // 최대 10개 슬라이딩 윈도우
   106→        if window.len() > 10 {
   107→            window.remove(0);
   108→        }
   109→
   110→        // N-gram 업데이트
   111→        if window.len() >= 2 {
   112→            let bigram = vec![window[window.len() - 2], window[window.len() - 1]];
   113→            *self.ngram_counts.entry(bigram).or_insert(0) += 1;
   114→        }
   115→        if window.len() >= 3 {
   116→            let trigram = vec![
   117→                window[window.len() - 3],
   118→                window[window.len() - 2],
   119→                window[window.len() - 1],
   120→            ];
   121→            *self.ngram_counts.entry(trigram).or_insert(0) += 1;
   122→        }
   123→        if window.len() >= 4 {
   124→            let fourgram = vec![
   125→                window[window.len() - 4],
   126→                window[window.len() - 3],
   127→                window[window.len() - 2],
   128→                window[window.len() - 1],
   129→            ];
   130→            *self.ngram_counts.entry(fourgram).or_insert(0) += 1;
   131→        }
   132→    }
   133→
   134→    pub fn get_anomaly_score(&self, ngram: &[u8]) -> f64 {
   135→        let count = self.ngram_counts.get(ngram).copied().unwrap_or(0);
   136→        let baseline = self.normal_baseline.get(ngram).copied().unwrap_or(0.1);
   137→
   138→        // Anomaly = (actual - baseline) / (baseline + 1)
   139→        if count as f64 > baseline {
   140→            (count as f64 - baseline) / (baseline + 1.0)
   141→        } else {
   142→            0.0
   143→        }
   144→    }
   145→
   146→    pub fn compute_entropy(pid: u32, extractor: &NgramExtractor) -> f64 {
   147→        if let Some(window) = extractor.per_pid_windows.get(&pid) {
   148→            if window.is_empty() {
   149→                return 0.0;
   150→            }
   151→
   152→            let mut freq = HashMap::new();
   153→            for &syscall in window {
   154→                *freq.entry(syscall).or_insert(0) += 1;
   155→            }
   156→
   157→            let mut entropy = 0.0;
   158→            let len = window.len() as f64;
   159→
   160→            for count in freq.values() {
   161→                let p = *count as f64 / len;
   162→                if p > 0.0 {
   163→                    entropy -= p * p.log2();
   164→                }
   165→            }
   166→
   167→            entropy / 5.0  // 정규화 (최대 log2(32) ≈ 5)
   168→        } else {
   169→            0.0
   170→        }
   171→    }
   172→}
