    56→// 2. 시스콜 이벤트 특성 벡터 (16차원)
    57→// ============================================================================
    58→
    59→pub struct SyscallFeatures {
    60→    pub syscall_id: f32,          // 시스콜 ID (0-400)
    61→    pub arg_count: f32,           // 인자 개수
    62→    pub user_id: f32,             // 사용자 ID
    63→    pub process_id: f32,          // 프로세스 ID
    64→    pub parent_pid: f32,          // 부모 프로세스 ID
    65→    pub file_access_count: f32,   // 파일 접근 횟수
    66→    pub privilege_level: f32,     // 권한 수준 (0.0-1.0)
    67→    pub memory_access: f32,       // 메모리 접근 여부
    68→    pub suspicious_args: f32,     // 의심스러운 인자 여부
    69→    pub sequence_anomaly: f32,    // 시퀀스 이상 점수
    70→    pub timing_anomaly: f32,      // 타이밍 이상 점수
    71→    pub ipc_entropy: f32,         // IPC 엔트로피
    72→    pub return_value: f32,        // 반환값 (-1=오류, 0=성공, 1=특수)
    73→    pub flags: f32,               // 플래그 비트마스크
    74→    pub access_pattern: f32,      // 접근 패턴 (읽기/쓰기/실행)
    75→    pub anomaly_score: f32,       // 종합 이상 점수 (0.0-1.0)
    76→}
    77→
    78→impl SyscallFeatures {
    79→    pub fn new() -> Self {
    80→        SyscallFeatures {
    81→            syscall_id: 0.0,
    82→            arg_count: 0.0,
    83→            user_id: 0.0,
    84→            process_id: 0.0,
    85→            parent_pid: 0.0,
    86→            file_access_count: 0.0,
    87→            privilege_level: 0.0,
    88→            memory_access: 0.0,
    89→            suspicious_args: 0.0,
    90→            sequence_anomaly: 0.0,
    91→            timing_anomaly: 0.0,
    92→            ipc_entropy: 0.0,
    93→            return_value: 0.0,
    94→            flags: 0.0,
    95→            access_pattern: 0.0,
    96→            anomaly_score: 0.0,
    97→        }
    98→    }
    99→
   100→    pub fn to_feature_vector(&self) -> [f32; 16] {
   101→        [
   102→            self.syscall_id / 400.0,
   103→            self.arg_count / 10.0,
   104→            self.user_id / 1000.0,
   105→            self.process_id / 100000.0,
   106→            self.parent_pid / 100000.0,
   107→            self.file_access_count / 100.0,
   108→            self.privilege_level,
   109→            self.memory_access,
   110→            self.suspicious_args,
   111→            self.sequence_anomaly,
   112→            self.timing_anomaly,
   113→            self.ipc_entropy,
   114→            (self.return_value + 1.0) / 2.0,  // -1~1 → 0~1
   115→            self.flags / 255.0,
   116→            self.access_pattern / 3.0,
   117→            self.anomaly_score,
   118→        ]
   119→    }
   120→
   121→    pub fn validate(&self) -> bool {
   122→        self.syscall_id >= 0.0 && self.syscall_id <= 400.0 &&
   123→        self.privilege_level >= 0.0 && self.privilege_level <= 1.0 &&
   124→        self.anomaly_score >= 0.0 && self.anomaly_score <= 1.0 &&
   125→        self.sequence_anomaly >= 0.0 && self.sequence_anomaly <= 1.0 &&
   126→        self.timing_anomaly >= 0.0 && self.timing_anomaly <= 1.0
   127→    }
   128→}
