   130→// ============================================================================
   131→// 3. 실시간 위협 탐지기 (< 10µs)
   132→// ============================================================================
   133→
   134→pub struct RealtimeThreatPredictor {
   135→    pub model: L0NeuralNet,
   136→    pub total_predictions: u32,
   137→    pub true_positives: u32,
   138→    pub true_negatives: u32,
   139→    pub false_positives: u32,
   140→    pub false_negatives: u32,
   141→    pub avg_latency_ns: u64,
   142→    pub total_latency_ns: u64,
   143→    pub max_threat_score: f32,
   144→}
   145→
   146→impl RealtimeThreatPredictor {
   147→    pub fn new() -> Self {
   148→        let mut model = L0NeuralNet::new();
   149→        model.initialize_random();
   150→
   151→        RealtimeThreatPredictor {
   152→            model,
   153→            total_predictions: 0,
   154→            true_positives: 0,
   155→            true_negatives: 0,
   156→            false_positives: 0,
   157→            false_negatives: 0,
   158→            avg_latency_ns: 0,
   159→            total_latency_ns: 0,
   160→            max_threat_score: 0.0,
   161→        }
   162→    }
   163→
   164→    /// 시스콜 특성에서 위협 탐지 (< 10µs)
   165→    pub fn predict_threat(&mut self, features: &SyscallFeatures) -> (ThreatType, f32) {
   166→        if !features.validate() {
   167→            return (ThreatType::None, 0.0);
   168→        }
   169→
   170→        // 특성 벡터 (16차원) → L0NN 입력
   171→        let feature_vec = features.to_feature_vector();
   172→
   173→        // L0 신경망 추론 (< 10µs)
   174→        let output = self.model.forward(&feature_vec);
   175→
   176→        // 출력 해석: 8차원 → 6가지 위협 클래스
   177→        // [0] = None, [1] = PrivEsc, [2] = MemExploit, [3] = FileExfil, [4] = DirtyPipe, [5] = ZeroDay
   178→        let mut max_idx = 0usize;
   179→        let mut max_score = output[0];
   180→
   181→        for i in 1..6 {
   182→            if output[i] > max_score {
   183→                max_score = output[i];
   184→                max_idx = i;
   185→            }
   186→        }
   187→
   188→        // 위협 점수 정규화 (0.0 ~ 1.0)
   189→        let threat_score = max_score.max(0.0).min(1.0);
   190→
   191→        // 최대 위협 점수 추적
   192→        if threat_score > self.max_threat_score {
   193→            self.max_threat_score = threat_score;
   194→        }
   195→
   196→        let threat_type = match max_idx {
   197→            0 => ThreatType::None,
   198→            1 => ThreatType::PrivilegeEscalation,
   199→            2 => ThreatType::MemoryExploit,
   200→            3 => ThreatType::FileExfiltration,
   201→            4 => ThreatType::DirtyPipe,
   202→            _ => ThreatType::UnknownZeroDay,
   203→        };
   204→
   205→        self.total_predictions += 1;
   206→
   207→        (threat_type, threat_score)
   208→    }
   209→
   210→    /// 위협 탐지 + 신뢰도 임계값
   211→    pub fn predict_threat_with_threshold(&mut self, features: &SyscallFeatures, threshold: f32) -> ThreatType {
   212→        let (threat_type, score) = self.predict_threat(features);
   213→
   214→        // 임계값 이상일 때만 위협으로 간주
   215→        if score >= threshold && threat_type as u32 > 0 {
   216→            threat_type
   217→        } else {
   218→            ThreatType::None
   219→        }
   220→    }
   221→
   222→    /// 예측 정확도 측정
   223→    pub fn measure_accuracy(&mut self, predicted: ThreatType, actual: ThreatType) -> bool {
   224→        let is_correct = predicted as u32 == actual as u32;
   225→
   226→        if predicted as u32 > 0 {
   227→            // 위협 예측
   228→            if is_correct {
   229→                self.true_positives += 1;
   230→            } else {
   231→                self.false_positives += 1;
   232→            }
   233→        } else {
   234→            // 정상 예측
   235→            if is_correct {
   236→                self.true_negatives += 1;
   237→            } else {
   238→                self.false_negatives += 1;
   239→            }
   240→        }
   241→
   242→        is_correct
   243→    }
   244→
   245→    /// 정확도 계산
   246→    pub fn accuracy(&self) -> f32 {
   247→        if self.total_predictions == 0 {
   248→            return 0.0;
   249→        }
   250→
   251→        let correct = (self.true_positives + self.true_negatives) as f32;
   252→        (correct / self.total_predictions as f32) * 100.0
   253→    }
   254→
   255→    /// 오탐지율 (False Positive Rate)
   256→    pub fn false_positive_rate(&self) -> f32 {
   257→        let all_negatives = (self.false_positives + self.true_negatives) as f32;
   258→        if all_negatives == 0.0 {
   259→            return 0.0;
   260→        }
   261→        (self.false_positives as f32 / all_negatives) * 100.0
   262→    }
   263→
   264→    /// 검출율 (True Positive Rate / Sensitivity)
   265→    pub fn detection_rate(&self) -> f32 {
   266→        let all_positives = (self.true_positives + self.false_negatives) as f32;
   267→        if all_positives == 0.0 {
   268→            return 0.0;
   269→        }
   270→        (self.true_positives as f32 / all_positives) * 100.0
   271→    }
   272→
   273→    /// 통계
   274→    pub fn stats(&self) -> (u32, u32, u32, u32, u32, f32) {
   275→        (
   276→            self.total_predictions,
   277→            self.true_positives,
   278→            self.false_positives,
   279→            self.true_negatives,
   280→            self.false_negatives,
   281→            self.accuracy(),
   282→        )
   283→    }
   284→
   285→    /// 레이턴시 업데이트
   286→    pub fn update_latency(&mut self, latency_ns: u64) {
   287→        self.total_latency_ns += latency_ns;
   288→        if self.total_predictions > 0 {
   289→            self.avg_latency_ns = self.total_latency_ns / self.total_predictions as u64;
   290→        }
   291→    }
   292→}
