   197→            dvfs_state: DvfsState::P1,  // 기본: P1 (1.5GHz)
   198→            dvfs_changes: 0,
   199→            thermal: ThermalState::new(),
   200→            autonomous_decisions: 0,
   201→            total_decisions: 0,
   202→            improvement_pct: 0.0,
