   240→    /// 자율적 최적화 결정 (L0NN 기반)
   241→    pub fn make_autonomous_decision(&mut self) -> DvfsState {
   242→        self.total_decisions += 1;
   243→        self.monitoring_cycles += 1;
   244→
   245→        // 현재 메트릭을 특성 벡터로 변환
   246→        let features = self.current_metrics.to_feature_vector();
   247→
   248→        // L0NN 추론 (시뮬레이션: 단순 휴리스틱)
   249→        let next_state = if self.thermal.should_throttle() {
   250→            // 온도 높음 → 주파수 낮춤
   251→            DvfsState::P4
   252→        } else if self.current_metrics.cpu_utilization > 0.8 {
   253→            // 높은 CPU 사용률 → P0 (최고 성능)
   254→            DvfsState::P0
   255→        } else if self.current_metrics.cpu_utilization < 0.3 {
   256→            // 낮은 CPU 사용률 → P4 (저전력)
   257→            DvfsState::P4
   258→        } else {
   259→            // 중간 → P2
   260→            DvfsState::P2
   261→        };
   262→
   263→        // DVFS 상태 변경
   264→        if next_state != self.dvfs_state {
   265→            self.dvfs_state = next_state;
   266→            self.dvfs_changes += 1;
   267→        }
   268→
   269→        self.autonomous_decisions += 1;
   270→
   271→        // 개선율 계산
   272→        let improvement = self.calculate_improvement();
   273→        self.improvement_pct = improvement;
   274→
   275→        next_state
   276→    }
   277→
   278→    /// 시스템 상태 모니터링
