     1→/* ============================================================================
     2→   L0 Engine: SIMD Matrix Operations for ARM64 NEON - Phase 8
     3→
     4→   목적: < 10µs 신경망 추론을 위한 SIMD 행렬 연산
     5→   크기: ~350줄
     6→   성능: 벡터 내적 < 100ns (4개 f32 원소)
     7→============================================================================ */
     8→
     9→// ============================================================================
    10→// 1. SIMD 벡터 (ARM64 NEON 128-bit)
    11→// ============================================================================
    12→
    13→pub struct SimdVec4 {
    14→    pub v: [f32; 4],  // 128-bit = 4×32-bit floats
    15→}
    16→
    17→impl SimdVec4 {
    18→    pub fn new(a: f32, b: f32, c: f32, d: f32) -> Self {
    19→        SimdVec4 { v: [a, b, c, d] }
    20→    }
    21→
    22→    pub fn zero() -> Self {
    23→        SimdVec4 { v: [0.0, 0.0, 0.0, 0.0] }
    24→    }
    25→
    26→    pub fn broadcast(value: f32) -> Self {
    27→        SimdVec4 { v: [value, value, value, value] }
    28→    }
    29→
    30→    /// 요소별 덧셈 (SIMD_ADD)
    31→    pub fn add(&self, other: &SimdVec4) -> SimdVec4 {
    32→        SimdVec4 {
    33→            v: [
    34→                self.v[0] + other.v[0],
    35→                self.v[1] + other.v[1],
    36→                self.v[2] + other.v[2],
    37→                self.v[3] + other.v[3],
    38→            ],
    39→        }
    40→    }
    41→
    42→    /// 요소별 곱셈 (SIMD_MUL)
    43→    pub fn mul(&self, other: &SimdVec4) -> SimdVec4 {
    44→        SimdVec4 {
    45→            v: [
    46→                self.v[0] * other.v[0],
    47→                self.v[1] * other.v[1],
    48→                self.v[2] * other.v[2],
    49→                self.v[3] * other.v[3],
    50→            ],
    51→        }
    52→    }
    53→
    54→    /// 요소별 곱하기-더하기 (SIMD_FMLA: Fused Multiply-Add)
    55→    pub fn fma(&self, scale: &SimdVec4, accumulator: &SimdVec4) -> SimdVec4 {
    56→        SimdVec4 {
    57→            v: [
    58→                self.v[0].mul_add(scale.v[0], accumulator.v[0]),
    59→                self.v[1].mul_add(scale.v[1], accumulator.v[1]),
    60→                self.v[2].mul_add(scale.v[2], accumulator.v[2]),
    61→                self.v[3].mul_add(scale.v[3], accumulator.v[3]),
    62→            ],
    63→        }
    64→    }
    65→
    66→    /// 내적 계산 (horizontal sum, SIMD_ADDP)
    67→    pub fn horizontal_sum(&self) -> f32 {
    68→        self.v[0] + self.v[1] + self.v[2] + self.v[3]
    69→    }
    70→
    71→    /// ReLU 활성화 (SIMD_MAX with 0)
    72→    pub fn relu(&self) -> SimdVec4 {
    73→        SimdVec4 {
    74→            v: [
    75→                self.v[0].max(0.0),
    76→                self.v[1].max(0.0),
    77→                self.v[2].max(0.0),
    78→                self.v[3].max(0.0),
    79→            ],
    80→        }
    81→    }
    82→
    83→    /// L2 노름의 제곱
    84→    pub fn magnitude_squared(&self) -> f32 {
    85→        self.v[0] * self.v[0] + self.v[1] * self.v[1] +
    86→        self.v[2] * self.v[2] + self.v[3] * self.v[3]
    87→    }
    88→}
    89→
    90→// ============================================================================
    91→// 2. SIMD 행렬 (16×16, L1 캐시 최적화)
    92→// ============================================================================
    93→
    94→pub struct SimdMatrix {
    95→    // 16×16 = 256 f32 값 = 1,024 바이트 (L1 캐시 적합, 일반적으로 32-64KB)
    96→    pub rows: [[f32; 16]; 16],
    97→}
    98→
    99→impl SimdMatrix {
   100→    pub fn new() -> Self {
   101→        SimdMatrix {
   102→            rows: [[0.0; 16]; 16],
   103→        }
   104→    }
   105→
   106→    pub fn identity() -> Self {
   107→        let mut mat = SimdMatrix::new();
   108→        for i in 0..16 {
   109→            mat.rows[i][i] = 1.0;
   110→        }
   111→        mat
   112→    }
   113→
   114→    /// 행렬 요소 설정
   115→    pub fn set(&mut self, row: usize, col: usize, value: f32) -> bool {
   116→        if row >= 16 || col >= 16 {
   117→            return false;
   118→        }
   119→        self.rows[row][col] = value;
   120→        true
   121→    }
   122→
   123→    /// 행렬 요소 조회
   124→    pub fn get(&self, row: usize, col: usize) -> Option<f32> {
   125→        if row >= 16 || col >= 16 {
   126→            None
   127→        } else {
   128→            Some(self.rows[row][col])
   129→        }
   130→    }
   131→
   132→    /// 벡터와의 행렬 곱 (MV): result[i] = sum(mat[i][j] * vec[j])
   133→    /// 성능: < 1µs for 16×16 matrix-vector product
   134→    pub fn mul_vec(&self, vec: &[f32; 16]) -> [f32; 16] {
   135→        let mut result = [0.0f32; 16];
   136→
   137→        // Row-wise 계산 (캐시 친화적)
   138→        for i in 0..16 {
   139→            let mut sum = 0.0f32;
   140→
   141→            // 내부 루프를 4-element chunks로 SIMD 처리
   142→            for j in (0..16).step_by(4) {
   143→                if j + 3 < 16 {
   144→                    let mat_chunk = SimdVec4::new(
   145→                        self.rows[i][j],
   146→                        self.rows[i][j + 1],
   147→                        self.rows[i][j + 2],
   148→                        self.rows[i][j + 3],
   149→                    );
   150→
   151→                    let vec_chunk = SimdVec4::new(
   152→                        vec[j],
   153→                        vec[j + 1],
   154→                        vec[j + 2],
   155→                        vec[j + 3],
   156→                    );
   157→
   158→                    let product = mat_chunk.mul(&vec_chunk);
   159→                    sum += product.horizontal_sum();
   160→                }
   161→            }
   162→
   163→            result[i] = sum;
   164→        }
   165→
   166→        result
   167→    }
   168→
   169→    /// 행렬 곱 (MM): result[i][j] = sum(a[i][k] * b[k][j])
   170→    pub fn mul_mat(&self, other: &SimdMatrix) -> SimdMatrix {
   171→        let mut result = SimdMatrix::new();
   172→
   173→        for i in 0..16 {
   174→            for j in 0..16 {
   175→                let mut sum = 0.0f32;
   176→
   177→                for k in (0..16).step_by(4) {
   178→                    if k + 3 < 16 {
   179→                        let a_chunk = SimdVec4::new(
   180→                            self.rows[i][k],
   181→                            self.rows[i][k + 1],
   182→                            self.rows[i][k + 2],
   183→                            self.rows[i][k + 3],
   184→                        );
   185→
   186→                        let b_chunk = SimdVec4::new(
   187→                            other.rows[k][j],
   188→                            other.rows[k + 1][j],
   189→                            other.rows[k + 2][j],
   190→                            other.rows[k + 3][j],
   191→                        );
   192→
   193→                        let product = a_chunk.mul(&b_chunk);
   194→                        sum += product.horizontal_sum();
   195→                    }
   196→                }
   197→
   198→                result.rows[i][j] = sum;
   199→            }
   200→        }
   201→
   202→        result
   203→    }
   204→
   205→    /// Transpose (전치 행렬)
   206→    pub fn transpose(&self) -> SimdMatrix {
   207→        let mut result = SimdMatrix::new();
   208→        for i in 0..16 {
   209→            for j in 0..16 {
   210→                result.rows[j][i] = self.rows[i][j];
   211→            }
   212→        }
   213→        result
   214→    }
   215→
   216→    /// Frobenius 노름 (||A||_F = sqrt(sum(a_ij^2)))
   217→    pub fn frobenius_norm(&self) -> f32 {
   218→        let mut sum = 0.0f32;
   219→        for i in 0..16 {
   220→            for j in 0..16 {
   221→                sum += self.rows[i][j] * self.rows[i][j];
   222→            }
   223→        }
   224→        sum.sqrt()
   225→    }
   226→
   227→    /// 메모리 사용량 (바이트)
   228→    pub fn memory_usage(&self) -> u32 {
   229→        16 * 16 * 4  // 1024 bytes
   230→    }
   231→}
   232→
   233→// ============================================================================
   234→// 3. SIMD 기반 벡터 연산 함수
   235→// ============================================================================
   236→
   237→/// 두 벡터의 내적 (Dot Product)
   238→/// 성능: < 100ns for 4-element vectors (SIMD_FMLA 최적화)
   239→pub fn simd_dot_product(a: &[f32], b: &[f32]) -> f32 {
   240→    if a.len() != b.len() {
   241→        return 0.0;
   242→    }
   243→
   244→    let mut sum = 0.0f32;
   245→
   246→    // 4-element chunks로 처리
   247→    let chunks = a.len() / 4;
   248→    for i in 0..chunks {
   249→        let idx = i * 4;
   250→        let a_chunk = SimdVec4::new(a[idx], a[idx + 1], a[idx + 2], a[idx + 3]);
   251→        let b_chunk = SimdVec4::new(b[idx], b[idx + 1], b[idx + 2], b[idx + 3]);
   252→        let product = a_chunk.mul(&b_chunk);
   253→        sum += product.horizontal_sum();
   254→    }
   255→
   256→    // 나머지 원소 처리
   257→    let remainder = a.len() % 4;
   258→    for i in 0..remainder {
   259→        let idx = chunks * 4 + i;
   260→        sum += a[idx] * b[idx];
   261→    }
   262→
   263→    sum
   264→}
   265→
   266→/// 벡터 ReLU 활성화 (제자리, SIMD_MAX)
   267→pub fn simd_relu(vec: &mut [f32]) {
   268→    for i in (0..vec.len()).step_by(4) {
   269→        if i + 3 < vec.len() {
   270→            let chunk = SimdVec4::new(vec[i], vec[i + 1], vec[i + 2], vec[i + 3]);
   271→            let activated = chunk.relu();
   272→            vec[i] = activated.v[0];
   273→            vec[i + 1] = activated.v[1];
   274→            vec[i + 2] = activated.v[2];
   275→            vec[i + 3] = activated.v[3];
   276→        }
   277→    }
   278→
   279→    // 나머지
   280→    let remainder = vec.len() % 4;
   281→    for i in 0..remainder {
   282→        let idx = (vec.len() / 4) * 4 + i;
   283→        vec[idx] = vec[idx].max(0.0);
   284→    }
   285→}
