   288→// 4. 검증 함수
   289→// ============================================================================
   290→
   291→pub fn validate_simd_vec4(v: &SimdVec4) -> bool {
   292→    for &val in &v.v {
   293→        if val.is_nan() || val.is_infinite() {
   294→            return false;
   295→        }
   296→    }
   297→    true
   298→}
   299→
   300→pub fn validate_simd_matrix(m: &SimdMatrix) -> bool {
   301→    for i in 0..16 {
   302→        for j in 0..16 {
   303→            if m.rows[i][j].is_nan() || m.rows[i][j].is_infinite() {
   304→                return false;
   305→            }
   306→        }
   307→    }
   308→    true
   309→}
   310→
   311→/// SIMD 행렬 곱셈 정확도 검증 (오차 < 1e-5)
   312→pub fn validate_simd_accuracy(expected: &[f32], actual: &[f32]) -> bool {
   313→    if expected.len() != actual.len() {
   314→        return false;
   315→    }
   316→
   317→    for i in 0..expected.len() {
   318→        let error = (expected[i] - actual[i]).abs();
   319→        if error > 1e-5 {
   320→            return false;
   321→        }
   322→    }
   323→
   324→    true
   325→}
